import { chromium } from 'playwright';

const BASE = 'http://127.0.0.1:4173/';
const results = [];
const check = (name, ok, extra = '') => {
  results.push({ name, ok });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? `  (${extra})` : ''}`);
};

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const consoleErrors = [];
page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
page.on('pageerror', (err) => consoleErrors.push(String(err)));

const headerTexts = () => page.$$eval('thead th', (ths) => ths.map((th) => th.textContent.trim()));
const rowCount = () => page.$$eval('tbody tr:not(.group-row)', (rows) => rows.length);
const groupCount = () => page.$$eval('tbody tr.group-row', (rows) => rows.length);

await page.goto(BASE, { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });

// --- Главная и группировка
check('home page heading', (await page.textContent('h1')) === 'Главная');
check('grouped by default: 5 status groups', (await groupCount()) === 5, `groups=${await groupCount()}`);
check('all 150 orders rendered', (await rowCount()) === 150, `rows=${await rowCount()}`);

// --- Навигация по разделам
await page.getByRole('button', { name: 'Заказы' }).click();
check('nav to Заказы changes heading', (await page.textContent('h1')) === 'Заказы');
check('nav active item marked aria-current', (await page.getAttribute('nav button[aria-current="page"]', 'aria-current')) === 'page');
await page.getByRole('button', { name: 'Пользователи' }).click();
check('nav to Пользователи shows placeholder', (await page.textContent('h1')) === 'Пользователи');
await page.getByRole('button', { name: 'Настройки' }).click();
check('nav to Настройки shows placeholder', (await page.textContent('h1')) === 'Настройки');
await page.getByRole('button', { name: 'Заказы' }).click();

// --- Сворачивание сайдбара
const sidebarWidth = () => page.$eval('.sidebar', (el) => el.getBoundingClientRect().width);
check('sidebar expanded initially', (await sidebarWidth()) > 200, `w=${await sidebarWidth()}`);
await page.getByRole('button', { name: 'Свернуть меню' }).click();
await page.waitForTimeout(350);
check('sidebar collapses to icon rail', (await sidebarWidth()) < 80, `w=${await sidebarWidth()}`);
check('collapsed nav items keep accessible names', (await page.getByRole('button', { name: 'Заказы' }).count()) === 1);
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(350);
check('collapsed state persists across reload', (await sidebarWidth()) < 80);
await page.screenshot({ path: '/tmp/e2e/shot-collapsed.png' });
await page.getByRole('button', { name: 'Развернуть меню' }).click();
await page.waitForTimeout(350);
check('sidebar expands again', (await sidebarWidth()) > 200);

// --- Выделение строк
const firstRowCheckbox = page.locator('tbody tr:not(.group-row) [aria-label^="Выбрать заказ"]').first();
await firstRowCheckbox.click({ force: true });
check('selecting a row shows counter', (await page.textContent('.orders-toolbar__right')).includes('Выбрано: 1'));
check('selected row gets is-selected', (await page.$$('tr.is-selected')).length === 1);
await page.getByRole('button', { name: 'Снять выделение' }).click();
check('clear selection resets counter', (await page.$$('tr.is-selected')).length === 0);

const headerCheckbox = page.locator('[aria-label="Выбрать все заказы"]').first();
await headerCheckbox.click({ force: true });
check('select-all selects all 150', (await page.$$('tr.is-selected')).length === 150);
await headerCheckbox.click({ force: true });
check('select-all again clears all', (await page.$$('tr.is-selected')).length === 0);

// --- Сворачивание группы
const firstGroupToggle = page.locator('.group-toggle').first();
const before = await rowCount();
await firstGroupToggle.click();
const afterCollapse = await rowCount();
check('collapsing a group hides its rows', afterCollapse < before, `${before} -> ${afterCollapse}`);
check('group aria-expanded=false after collapse', (await firstGroupToggle.getAttribute('aria-expanded')) === 'false');
await firstGroupToggle.click();
check('expanding a group restores rows', (await rowCount()) === before);

// --- Перетаскивание колонок мышью
const initial = await headerTexts();
check('default column order', initial.join('|') === 'Заказ|Клиент|Город|Позиции|Сумма|Дата|Статус' || initial.length === 8, initial.join(' | '));
const headers = page.locator('thead th');
await page.dragAndDrop('thead th:has-text("Сумма")', 'thead th:has-text("Заказ")');
const afterDrag = await headerTexts();
check('drag "Сумма" onto "Заказ" moves it to first place', afterDrag[1] === 'Сумма', afterDrag.join(' | '));
check('checkbox column stays pinned first', afterDrag[0] === '' || afterDrag.length === 8, `count=${afterDrag.length}`);
const reorderBtn = page.getByRole('button', { name: 'Сбросить порядок колонок' });
check('reset-columns button appears after reorder', (await reorderBtn.count()) === 1);
await page.screenshot({ path: '/tmp/e2e/shot-dragged.png' });

// --- Клавиатурная перестановка (Alt + стрелки)
await page.locator('thead th:has-text("Город")').focus();
await page.keyboard.press('Alt+ArrowLeft');
const afterKey = await headerTexts();
check('Alt+ArrowLeft moves focused column left', afterKey.indexOf('Город') < afterDrag.indexOf('Город'), afterKey.join(' | '));

await reorderBtn.click();
const restored = await headerTexts();
check('reset restores default column order', restored.join('|') === 'Заказ|Клиент|Город|Позиции|Сумма|Дата|Статус', restored.join(' | '));

// --- Выключаем группировку
await page.getByText('Группировать по статусу').click();
check('ungrouped: no group rows', (await groupCount()) === 0);
check('ungrouped: all 150 rows visible', (await rowCount()) === 150);
await page.getByText('Группировать по статусу').click();

// --- Выделение внутри группы через чекбокс группы
const groupCheckbox = page.locator('tr.group-row [aria-label^="Выбрать все заказы:"]').first();
await groupCheckbox.click({ force: true });
const groupSelected = (await page.$$('tr.is-selected')).length;
check('group checkbox selects every order in that group', groupSelected > 0 && groupSelected < 150, `selected=${groupSelected}`);
await page.screenshot({ path: '/tmp/e2e/shot-main.png', fullPage: false });

check('no console errors', consoleErrors.length === 0, consoleErrors.slice(0, 3).join(' || '));

await browser.close();
const failed = results.filter((r) => !r.ok).length;
console.log(`\n${results.length - failed}/${results.length} checks passed`);
process.exit(failed ? 1 : 0);

